#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  # shellcheck disable=SC1087 # false positive: $e is a scalar, the [ is a literal bracket
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────


# Sets up the dev runtime from ADR 0005: rootless Podman under its own system user, its API on
# loopback TCP, and the sandbox settings that let Claude reach it through the sandbox proxy.
# Idempotent: re-running skips what is already in place.

REPO="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
RUNTIME_USER="homelab-runtime"
RUNTIME_HOME="/var/lib/$RUNTIME_USER"
SUBID_RANGE="165536-231071"            # after the operator's 100000-165535
API_PORT=8888
API_UNIT="homelab-podman-api.service"
KIND_VERSION="v0.33.0"
KIND_SHA256="aee6151561422756b764a4ae28e7f44cda5af5a9eead3cc9985112b1de8d8e0d"
KUBECTL_VERSION="v1.37.1"
KUBECTL_SHA256="65691ff77eb6fa44c908b77a1082c9f092c3b9733b5cefabec0d1104890e21a8"
FLUX_VERSION="2.9.6"
FLUX_SHA256="b4d22673e9246cbd628881f1a9ef3b090085dced291e42d804555cee8e8d42c5"
SETTINGS="$REPO/.claude/settings.json"
LOOPBACK_HOSTS='"127.0.0.1:8888", "127.0.0.1:6443", "127.0.0.1:5001"'

# as_runtime CMD...: run CMD as the runtime user from a directory it can enter.
as_runtime() { (cd / && sudo -u "$RUNTIME_USER" "$@"); }
# user_systemctl ARGS...: systemctl against the runtime user's own systemd instance.
user_systemctl() { sudo systemctl --user -M "$RUNTIME_USER@" "$@"; }
ok() { printf '  %s✓%s %s\n' "$GREEN" "$RESET" "$1"; }

# install_bin NAME URL SHA256 [TAR_MEMBER]: verified download into /usr/local/bin.
install_bin() {
  local name="$1" url="$2" sum="$3" member="${4:-}" tmp
  tmp=$(mktemp -d)
  curl -fsSLo "$tmp/dl" "$url"
  echo "$sum  $tmp/dl" | sha256sum -c --quiet
  if [[ -n "$member" ]]; then tar -xzf "$tmp/dl" -C "$tmp" "$member"; mv "$tmp/$member" "$tmp/dl"; fi
  sudo install -m 0755 "$tmp/dl" "/usr/local/bin/$name"
  rm -rf "$tmp"
  ok "$name installed: /usr/local/bin/$name"
}

run_wizard() {

TOTAL_STAGES=6

banner "Dev runtime: rootless Podman under its own user (ADR 0005)"

# ──────────────────────────────────────────────────────────────────────────
stage "Remove the rootful test cluster and registry"
say "Rung 1 ran Podman as root. Its cluster 'kind' and the kind-registry container"
say "are no longer needed; the new runtime starts clean."
if command -v podman >/dev/null && sudo podman container exists kind-control-plane 2>/dev/null; then
  if confirm "Delete the rootful cluster 'kind' and the kind-registry container?"; then
    sudo env KIND_EXPERIMENTAL_PROVIDER=podman kind delete cluster --name kind
    sudo podman rm -f kind-registry >/dev/null 2>&1 || true
    ok "rootful cluster and registry removed"
  fi
  note "Root's image store still holds the node and registry images (about 1 GB)."
  if confirm "Wipe root's Podman storage too (sudo podman system reset)? Nothing else uses it."; then
    sudo podman system reset --force
    ok "root's Podman storage wiped"
  fi
else
  ok "no rootful cluster found"
fi
pause

# ──────────────────────────────────────────────────────────────────────────
stage "Create the runtime user"
say "Containers run as '$RUNTIME_USER', a system user with no login shell and its"
say "own home at $RUNTIME_HOME. It cannot read your home (mode $(stat -c %a "$HOME")),"
say "so a container Claude starts cannot reach your SSH keys or the App key."
if id "$RUNTIME_USER" >/dev/null 2>&1; then
  ok "$RUNTIME_USER already exists"
else
  confirm "Create system user $RUNTIME_USER?" || { warn "stopped"; exit 1; }
  sudo useradd --system --create-home --home-dir "$RUNTIME_HOME" --shell /usr/sbin/nologin "$RUNTIME_USER"
  ok "created $RUNTIME_USER"
fi
sudo chmod 0700 "$RUNTIME_HOME"
if ! grep -q "^$RUNTIME_USER:" /etc/subuid; then
  sudo usermod --add-subuids "$SUBID_RANGE" --add-subgids "$SUBID_RANGE" "$RUNTIME_USER"
fi
ok "subordinate IDs: $(grep "^$RUNTIME_USER:" /etc/subuid)"
pause

# ──────────────────────────────────────────────────────────────────────────
stage "Delegate all cgroup controllers to user sessions"
say "Rootless kind needs cpu, cpuset, io, memory and pids in the user's cgroup."
say "systemd hands out only cpu, memory and pids by default."
dropin=/etc/systemd/system/user@.service.d/delegate.conf
want=$'[Service]\nDelegate=cpu cpuset io memory pids'
if [[ "$(cat "$dropin" 2>/dev/null)" == "$want" ]]; then
  ok "already delegated ($dropin)"
else
  confirm "Write $dropin and reload systemd?" || { warn "stopped"; exit 1; }
  sudo mkdir -p "$(dirname "$dropin")"
  printf '%s\n' "$want" | sudo tee "$dropin" >/dev/null
  sudo systemctl daemon-reload
  ok "wrote $dropin"
fi
uid=$(id -u "$RUNTIME_USER")
if systemctl is-active --quiet "user@$uid.service"; then
  sudo systemctl restart "user@$uid.service"   # pick up the delegation
fi
pause

# ──────────────────────────────────────────────────────────────────────────
stage "Start the runtime user's Podman API on 127.0.0.1:$API_PORT"
say "Lingering keeps $RUNTIME_USER's systemd running without a login. A user service"
say "serves its Podman API on loopback TCP; Claude reaches that port through the"
say "sandbox proxy. Anything on this machine that can open 127.0.0.1:$API_PORT can"
say "drive $RUNTIME_USER's containers; no other user account exists here."
confirm "Enable lingering and install $API_UNIT?" || { warn "stopped"; exit 1; }
sudo loginctl enable-linger "$RUNTIME_USER"
for _ in $(seq 50); do [[ -d "/run/user/$uid" ]] && break; sleep 0.2; done
as_runtime mkdir -p "$RUNTIME_HOME/.config/systemd/user"
as_runtime tee "$RUNTIME_HOME/.config/systemd/user/$API_UNIT" >/dev/null <<UNIT
[Unit]
Description=Podman API for the homelab dev runtime (ADR 0005), loopback only

[Service]
Type=exec
# kind checks the controllers in this service's own cgroup; upstream podman.service sets it too.
Delegate=yes
ExecStart=/usr/bin/podman system service --time=0 tcp://127.0.0.1:$API_PORT
Restart=on-failure

[Install]
WantedBy=default.target
UNIT
# A system user cannot read its own entries back from the journal, so with the journald default
# `podman logs` comes back empty and kind never sees its node boot. Plain log files instead.
as_runtime mkdir -p "$RUNTIME_HOME/.config/containers"
as_runtime tee "$RUNTIME_HOME/.config/containers/containers.conf" >/dev/null <<CONF
[containers]
log_driver = "k8s-file"
CONF
user_systemctl daemon-reload
user_systemctl enable "$API_UNIT"
user_systemctl restart "$API_UNIT"   # a re-run picks up unit changes
for _ in $(seq 50); do curl -fsS "http://127.0.0.1:$API_PORT/_ping" >/dev/null 2>&1 && break; sleep 0.2; done
if [[ "$(curl -fsS "http://127.0.0.1:$API_PORT/_ping" 2>/dev/null)" == OK ]]; then
  ok "Podman API answers on 127.0.0.1:$API_PORT"
  CONTAINER_HOST="tcp://127.0.0.1:$API_PORT" podman info \
    --format '  rootless={{.Host.Security.Rootless}} cgroup={{.Host.CgroupsVersion}} controllers={{.Host.CgroupControllers}} net={{.Host.RootlessNetworkCmd}}'
  controllers=$(CONTAINER_HOST="tcp://127.0.0.1:$API_PORT" podman info --format '{{.Host.CgroupControllers}}')
  for c in cpu cpuset io memory pids; do
    [[ " ${controllers//[\[\]]/} " == *" $c "* ]] || { warn "controller $c missing; kind will refuse to start"; exit 1; }
  done
  ok "all five cgroup controllers reach the Podman API"
  logdriver=$(CONTAINER_HOST="tcp://127.0.0.1:$API_PORT" podman info --format '{{.Host.LogDriver}}')
  [[ "$logdriver" == k8s-file ]] || { warn "log driver is $logdriver, not k8s-file; kind will hang"; exit 1; }
  ok "container logs go to files (k8s-file)"
else
  warn "Podman API did not answer. Its log:"
  sudo journalctl _UID="$uid" -n 30 --no-pager || true
  exit 1
fi
pause

# ──────────────────────────────────────────────────────────────────────────
stage "Install kind, kubectl and flux"
say "Release binaries, checksums verified, into /usr/local/bin."
if [[ "$(kind version 2>/dev/null)" == *"$KIND_VERSION"* ]]; then ok "kind $KIND_VERSION present"
else install_bin kind "https://github.com/kubernetes-sigs/kind/releases/download/$KIND_VERSION/kind-linux-amd64" "$KIND_SHA256"; fi
if [[ "$(kubectl version --client 2>/dev/null)" == *"$KUBECTL_VERSION"* ]]; then ok "kubectl $KUBECTL_VERSION present"
else install_bin kubectl "https://dl.k8s.io/release/$KUBECTL_VERSION/bin/linux/amd64/kubectl" "$KUBECTL_SHA256"; fi
if [[ "$(flux version --client 2>/dev/null)" == *"$FLUX_VERSION"* ]]; then ok "flux $FLUX_VERSION present"
else install_bin flux "https://github.com/fluxcd/flux2/releases/download/v$FLUX_VERSION/flux_${FLUX_VERSION}_linux_amd64.tar.gz" "$FLUX_SHA256" flux; fi
pause

# ──────────────────────────────────────────────────────────────────────────
stage "Let the sandbox reach the runtime"
say "Claude cannot edit .claude/settings.json, so this stage does. Two changes:"
step "allowedDomains gains $LOOPBACK_HOSTS: the Podman API, the kind API server"
step "(unused since the SSH tunnel; drop it later) and the hl-tunnel SSH port (ADR 0018)."
step "excludedCommands (podman, docker) goes: it never took effect, and Claude now"
step "runs podman inside the sandbox as a client of the runtime user's API."
if grep -q '"127.0.0.1:8888"' "$SETTINGS" && ! grep -q '"excludedCommands"' "$SETTINGS"; then
  ok "settings already updated"
else
  confirm "Edit $SETTINGS?" || { warn "stopped"; exit 1; }
  tmp=$(mktemp)
  sed -e '/"excludedCommands": \["podman", "docker"\],/d' \
      -e "s/\"kind.sigs.k8s.io\", \"code.claude.com\", \"skills.sh\"\$/&,\n        $LOOPBACK_HOSTS/" \
      "$SETTINGS" > "$tmp"
  if jq -e '(.sandbox.network.allowedDomains | index("127.0.0.1:6443")) and (.sandbox.excludedCommands == null)' "$tmp" >/dev/null; then
    cat "$tmp" > "$SETTINGS"; rm -f "$tmp"
    ok "updated $SETTINGS"
  else
    rm -f "$tmp"
    warn "the edit did not apply cleanly; settings left unchanged. Make the two changes above by hand."
    SKIPPED+=("sandbox settings in $SETTINGS")
  fi
fi
say ""
step "Restart the Claude session (close and reopen it) so it loads the new settings."
pause

finish
note "Tell Claude the runtime is up; tools/hl-runtime starts the SSH tunnel and the cluster itself."
}

run_wizard "$@"; exit
